# owner: platform
"""Lay students out in seating rows."""

from typing import List
from rosterkit.models import Student


def _sort_key(student: Student):
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, names: List[str]) -> str:
    return f"Row {number}: " + " | ".join(names)


def _build_lines(names: List[str], seats: int) -> List[str]:
    starts = range(0, len(names), seats)
    return [
        _row_line(start // seats + 1, names[start:start + seats])
        for start in starts
    ]


# ---
def seat_rows(students: List[Student], seats: int):
    """One text line per row, students sorted by last name."""
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    return _build_lines(names, seats)

