# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make(last, first):
    return Student("id-" + last, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Arden", "Cass")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Arden, Cass | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_wide_row(self):
        people = [make("Zane", "Kit"), make("Abel", "Ona")]
        self.assertEqual(
            seat_rows(people, 9),
            ["Row 1: Abel, Ona | Zane, Kit"]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([make("Abel", "Ona")], 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([make("Abel", "Ona")], -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 4)
